#!/usr/bin/env bash
# allowed_signers and the context includes current, hooks present (problems). A missing
# signing key is a warning: keys are generated by the ssh preflight, and a fresh machine may not have them yet.
# Each identity's effective signing key must be one of its ssh keys (github.conf candidates).
# In each work folder, the effective config (after whatever other tools appended) must be the work identity.
set -euo pipefail
for f in log os link profile module contexts ssh git; do
  # shellcheck disable=SC1090
  source "$DOTFILES_DIR/lib/$f.sh"
done
cfg="$HOME/.config/git"
rc=0
contexts="$(contexts_collect)"
for ctx in personal work; do
  folder="$(printf '%s\n' "$contexts" | contexts_first_folder "$ctx")" || continue
  key="$(git_signing_key_in "$folder")"
  [ -n "$key" ] || continue
  if [ ! -f "$key" ]; then
    echo "warn: signing key missing for $ctx: $key (commits there will fail until it exists)"
  elif ! ssh_key_candidates "$ctx" | grep -qxF "${key%.pub}"; then
    echo "signing key for $ctx is $key, not one of its ssh keys: $(ssh_key_candidates "$ctx" | tr '\n' ' ')"
    rc=1
  fi
done
if ! dry="$(DRY_RUN=1 bash "$DOTFILES_DIR/modules/git/install.sh" 2>&1)"; then
  printf '%s\n' "$dry"
  echo "git install dry run failed"
  rc=1
fi
while IFS= read -r f; do
  [ -n "$f" ] || continue
  echo "missing or stale: $f (rerun install)"
  rc=1
done < <(printf '%s\n' "$dry" | sed -n 's/^\[dry\] write //p')
[ -e "$cfg/template/hooks/commit-msg" ] || {
  echo "missing template/hooks/commit-msg"
  rc=1
}
while IFS= read -r f; do
  [ -n "$f" ] || continue
  echo "repo without commit-msg hook: ${f%/.git/hooks/commit-msg} (dots install)"
  rc=1
done < <(printf '%s\n' "$dry" | sed -n 's/^\[dry\] hook -> //p')

# Prints one line per way FOLDER's effective git config differs from the work identity.
work_folder_mismatches() { # FOLDER WORK_EMAIL
  local folder="$1" want_email="$2" form url want got
  want="git@github.com-work:o/r.git"
  for form in git@github.com: https://github.com/ ssh://git@github.com/; do
    url="$(git_in_folder "$folder" ls-remote --get-url "${form}o/r.git")"
    [ "$url" = "$want" ] || echo "$folder: ${form}o/r.git resolves to $url, want $want"
  done
  got="$(git_in_folder "$folder" config user.email || true)"
  [ "$got" = "$want_email" ] || echo "$folder: user.email is $got, want $want_email"
  got="$(git_in_folder "$folder" config --bool commit.gpgsign || echo false)"
  [ "$got" = true ] || echo "$folder: commit.gpgsign is $got, want true"
}

if profile_identities "$(contexts_profile)" | grep -qx work; then
  work_email="$(git config --file "$cfg/identity.work" user.email || true)"
  while IFS=$'\t' read -r ctx folder; do
    if [ "$ctx" != work ] || [ ! -d "$folder" ]; then continue; fi
    mismatches="$(work_folder_mismatches "$folder" "$work_email")"
    if [ -n "$mismatches" ]; then
      printf '%s\n' "$mismatches"
      rc=1
    fi
  done <<<"$contexts"
fi
exit $rc
